    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []

    # Locate the 3x3 objects, each with a 2 at its center.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 2 and
                grid[r-1][c] == grid[r+1][c] ==
                grid[r][c-1] == grid[r][c+1] == 3):
                centers.append((r, c))

    for r, c in centers:
        row_twos = sum(v == 2 for v in grid[r])
        col_twos = sum(grid[i][c] == 2 for i in range(h))

        # Project perpendicular to the 2-line passing through the object.
        horizontal = col_twos >= row_twos
        if horizontal:
            path = [(r, j) for j in range(w)]
        else:
            path = [(i, c) for i in range(h)]

        for rr, cc in path:
            if grid[rr][cc] == 0:
                out[rr][cc] = 1

            # At crossings with another 2-line, make a 1-colored ring
            # around the 2, while leaving any 3-colored object cells intact.
            if grid[rr][cc] == 2:
                has_object_neighbor = any(
                    0 <= rr + dr < h and 0 <= cc + dc < w
                    and grid[rr + dr][cc + dc] == 3
                    for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                    if (dr, dc) != (0, 0)
                )
                if not has_object_neighbor:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = rr + dr, cc + dc
                            if ((dr, dc) != (0, 0) and
                                0 <= nr < h and 0 <= nc < w and
                                grid[nr][nc] != 3):
